def searchRange(nums, target):
    def lower(strict):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < target or (strict and nums[mid] == target):
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower(False)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, lower(True) - 1]
